typedef struct { double x, y; } mouse_t;

void mouse_track(void (*render)(void *ctx, const mouse_t *m), void *ctx) {
    mouse_t m = {0, 0};
    for (;;) {                      /* host event loop */
        m.x += 1; m.y += 2;
        render(ctx, &m);            /* caller decides the output */
    }
}

static void draw(void *ctx, const mouse_t *m) {
    printf("%s %g %g\n", (const char *)ctx, m->x, m->y);
}
